#include <vector>
#include <numeric>

class Solution {
public:
    int sumFourDivisors(std::vector<int>& nums) {
        int totalSum = 0;
        for (int x : nums) {
            std::vector<int> divs;
            for (int d = 1; d * d <= x; ++d) {
                if (x % d == 0) {
                    divs.push_back(d);
                    if (d * d != x) divs.push_back(x / d);
                }
                if (divs.size() > 4) break;
            }
            if (divs.size() == 4) {
                totalSum += std::accumulate(divs.begin(), divs.end(), 0);
            }
        }
        return totalSum;
    }
};

import java.util.*;

class Solution {
    public int sumFourDivisors(int[] nums) {
        int totalSum = 0;
        for (int x : nums) {
            List<Integer> divs = new ArrayList<>();
            for (int d = 1; d * d <= x; d++) {
                if (x % d == 0) {
                    divs.add(d);
                    if (d * d != x) divs.add(x / d);
                }
                if (divs.size() > 4) break;
            }
            if (divs.size() == 4) {
                for (int d : divs) totalSum += d;
            }
        }
        return totalSum;
    }
}

var sumFourDivisors = function(nums) {
    let totalSum = 0;
    for (const x of nums) {
        const divs = [];
        for (let d = 1; d * d <= x; d++) {
            if (x % d === 0) {
                divs.push(d);
                if (d * d !== x) divs.push(x / d);
            }
            if (divs.length > 4) break;
        }
        if (divs.length === 4) {
            totalSum += divs.reduce((acc, v) => acc + v, 0);
        }
    }
    return totalSum;
};
